const $=id=>document.getElementById(id), esc=value=>String(value??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const sourceRu={yandex_maps:'Яндекс Карты',two_gis:'2ГИС'},statusRu={queued:'В очереди',sending:'Отправляется',sent:'Отправлено',replied:'Получен ответ',bounced:'Не доставлено',opened:'Открыто',clicked:'Перешли по ссылке',unsubscribed:'Отписались',failed:'Ошибка',send_error:'Ошибка',paused:'Приостановлено',running:'Работает',completed:'Завершено',exhausted:'Завершено',blocked:'Нужна проверка'};
const pages={home:['Главная','Главное о работе системы'],companies:['Компании','Контакты и история работы с компаниями'],directions:['Направления','Где и какие компании искать'],phraseSearch:['Поиск по фразам','Поиск компаний на публичных сайтах'],letters:['Письма','Отправленные письма и их состояние'],templates:['Шаблоны','Готовые тексты для писем'],mailboxes:['Почтовые ящики','Почта для отправки писем и получения ответов'],sheets:['Google Таблица','Синхронизация компаний с таблицей'],analytics:['Аналитика','Результаты поиска, качество данных и письма'],settings:['Настройки','Основные параметры системы']};
let directions=[],companies=[],mailboxes=[],templates=[],deliveries=[],analyticsData=null,aiUsageData=null,currentAnalyticsTab='overview',periodDays=0,aiCompanyFilter='',aiOperationFilter='',aiUsageOffset=0,dirtyForm=null;
const modals={};

async function api(path,options={}){const response=await fetch(path,{...options,headers:{'Content-Type':'application/json','X-LeadFlow-CSRF':'1',...(options.headers||{})}});if(!response.ok){let message='Не удалось выполнить действие. Попробуйте ещё раз.';try{const body=await response.json();message=typeof body.detail==='string'?body.detail:message}catch{}throw Error(humanError(message))}return response.status===204?null:response.json()}
function humanError(message){const text=String(message).toLowerCase();if(text.includes('google')||text.includes('spreadsheet')||text.includes('worksheet')||text.includes('403'))return'Нет доступа к Google Таблице.';if(text.includes('smtp')||text.includes('почт')&&text.includes('auth'))return'Не удалось войти в почту. Проверьте адрес и пароль приложения.';if(text.includes('imap'))return'Не удалось проверить входящие письма.';if(text.includes('captcha')||text.includes('parser')||text.includes('source'))return'Источник поиска временно недоступен. Система попробует ещё раз.';if(text.includes('ai')||text.includes('provider'))return'Умное дополнение данных пока не подключено.';return message.match(/[А-Яа-яЁё]/)?message:'Не удалось выполнить действие. Попробуйте ещё раз.'}
function notify(text,error=false){$('toastText').textContent=text;$('toastIcon').textContent=error?'!':'✓';$('appToast').className=`toast ${error?'error':'success'}`;bootstrap.Toast.getOrCreateInstance($('appToast'),{delay:4200}).show()}
function busy(button,on,label='Идёт работа…'){if(!button)return;button.disabled=on;if(on){button.dataset.old=button.innerHTML;button.innerHTML=`<span class="spinner-border spinner-border-sm"></span> ${label}`}else if(button.dataset.old)button.innerHTML=button.dataset.old}
function dateText(value){if(!value)return'Ещё не было';return new Date(value).toLocaleString('ru-RU',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}
function money(value){const amount=Number(value||0);return'$'+amount.toLocaleString('ru-RU',{minimumFractionDigits:amount&&amount<.01?6:2,maximumFractionDigits:8})}
function publicLink(url,label='Открыть источник'){return /^https?:\/\//i.test(url||'')?`<a href="${esc(url)}" target="_blank" rel="noopener">${esc(label)}</a>`:'—'}
function optionRows(items,placeholder){return`<option value="">${placeholder}</option>`+items.map(x=>`<option value="${esc(x.id??x)}">${esc(x.name??x)}</option>`).join('')}
function metric(label,value,href=''){return`<div class="col-6 col-md-4 col-xl-2"><a class="metric-card" ${href?`href="${href}"`:''}><div class="metric-label">${esc(label)}</div><div class="metric-value">${value??0}</div></a></div>`}
function empty(message,hint='Попробуйте выбрать более длинный период.'){return`<div class="empty"><h3 class="h5">${esc(message)}</h3><p class="mb-0">${esc(hint)}</p></div>`}
function chart(title,rows,key='value'){if(!rows.length)return`<div class="chart-card">${empty('За выбранный период данных пока нет.')}</div>`;const max=Math.max(1,...rows.map(x=>Number(x[key]||0)));return`<div class="chart-card"><h3 class="h5">${esc(title)}</h3>${rows.map(x=>`<div class="bar-row"><span title="${esc(x.label||x.name||x.date)}">${esc(x.label||x.name||x.date)}</span><div class="bar-track"><div class="bar-fill" style="width:${Math.max(1,Number(x[key]||0)*100/max)}%"></div></div><strong>${x[key]||0}</strong></div>`).join('')}</div>`}

function buildMenus(){const icons={home:'⌂',companies:'▦',directions:'⌖',phraseSearch:'⌕',letters:'✉',templates:'▤',mailboxes:'◉',sheets:'▦',analytics:'◫',settings:'⚙'};const html=Object.entries(pages).map(([id,[label]])=>`<a class="nav-link section-link" data-section="${id}" href="#${id}"><span class="me-2">${icons[id]}</span>${label}</a>`).join('');$('desktopMenu').innerHTML=html;$('mobileMenu').innerHTML=html;document.querySelectorAll('.section-link').forEach(x=>x.onclick=e=>{e.preventDefault();showSection(x.dataset.section)})}
async function showSection(name,push=true){if(dirtyForm&&!confirm('Есть несохранённые изменения. Покинуть форму?'))return;document.querySelectorAll('.app-section').forEach(x=>x.classList.add('d-none'));$(`section-${name}`).classList.remove('d-none');document.querySelectorAll('.section-link').forEach(x=>x.classList.toggle('active',x.dataset.section===name));$('pageTitle').textContent=pages[name][0];$('pageSubtitle').textContent=pages[name][1];const action=$('primaryAction');action.classList.add('d-none');action.onclick=null;if(name==='directions'){action.textContent='+ Добавить направление';action.onclick=()=>openDirection();action.classList.remove('d-none');await loadDirections()}if(name==='phraseSearch')await loadPhraseSearch();if(name==='companies')await loadCompanies();if(name==='letters')await loadLetters();if(name==='templates'){action.textContent='+ Создать шаблон';action.onclick=()=>openTemplate();action.classList.remove('d-none');await loadTemplates()}if(name==='mailboxes'){action.textContent='+ Добавить почту';action.onclick=()=>openMailbox();action.classList.remove('d-none');await loadMailboxes()}if(name==='sheets')await loadSheets();if(name==='analytics')await loadAnalytics();if(name==='settings')await loadSettings();if(name==='home')await loadHome();if(push)history.replaceState(null,'',`#${name}`);bootstrap.Offcanvas.getInstance($('mobileNav'))?.hide()}

async function loadBase(){[directions,mailboxes,templates]=await Promise.all([api('/api/directions'),api('/api/mail-accounts'),api('/api/templates')])}
const phraseStatus={added:'Добавлено',duplicate:'Дубль',irrelevant:'Нерелевантно',error:'Ошибка'};
async function loadPhraseSearch(){try{if(!directions.length)await loadBase();$('phraseDirection').innerHTML=optionRows(directions,'Выберите направление');const rows=await api('/api/phrase-search/results');$('phraseResultRows').innerHTML=rows.map(x=>`<tr><td>${dateText(x.created_at)}</td><td><strong>${esc(x.direction)}</strong><div class="small text-secondary">${esc(x.phrase)}</div></td><td>${publicLink(x.source_url,'Открыть страницу')}</td><td><strong>${esc(x.company_name||'—')}</strong>${x.website?`<div class="small">${publicLink(x.website,x.website.replace(/^https?:\/\//,''))}</div>`:''}</td><td><div>${esc(x.email||'—')}</div><div>${esc(x.phone||'—')}</div></td><td>${x.extraction_method==='ai'?'ИИ':'Обычный поиск'}</td><td><span class="state-pill ${x.status==='error'?'off':''}" title="${esc(x.error||'')}">${phraseStatus[x.status]||esc(x.status)}</span></td></tr>`).join('');$('phraseEmpty').classList.toggle('d-none',rows.length>0)}catch(e){showGlobal(e.message)}}
$('phraseSearchForm').onsubmit=async e=>{e.preventDefault();const button=e.submitter,phrases=$('phraseValues').value.split('\n').map(x=>x.trim()).filter(Boolean);if(!phrases.length){notify('Добавьте хотя бы одну поисковую фразу.',true);return}busy(button,true,'Запускаем поиск…');try{await api('/api/phrase-search',{method:'POST',body:JSON.stringify({direction_id:$('phraseDirection').value,city:$('phraseCity').value.trim(),region:$('phraseRegion').value.trim()||null,phrases,limit:Number($('phraseLimit').value),use_ai:$('phraseAI').checked})});notify('Поиск запущен. Результаты появятся в истории.');setTimeout(loadPhraseSearch,2500)}catch(error){notify(error.message,true)}finally{busy(button,false)}};
async function loadHome(){try{analyticsData=await api('/api/analytics?date_from='+todayIso());const d=analyticsData,o=d.overview;$('healthBanner').classList.toggle('attention',!d.status.ok);$('healthBanner').innerHTML=`<div><div class="status-title">${esc(d.status.label)}</div><div class="status-subtitle">${d.status.ok?'Поиск, письма и синхронизация доступны':'Откройте пункты ниже, чтобы исправить проблему'}</div></div><span class="fs-3">${d.status.ok?'✓':'!'}</span>`;$('sideStatus').textContent=d.status.label;$('sideStatusDot').className=`status-dot bg-${d.status.ok?'success':'warning'}`;$('homeMetrics').innerHTML=[['Найдено компаний сегодня',o.found],['Новых компаний сегодня',o.new],['Отправлено писем сегодня',o.sent],['Получено ответов',o.replied],['Не доставлено',o.bounced],['Активных направлений',o.active_directions]].map(x=>metric(...x)).join('');$('recentActions').innerHTML=d.recent_actions.length?d.recent_actions.map(x=>`<div class="timeline-item"><div class="timeline-time">${new Date(x.at).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}</div><div>${esc(x.text)}</div></div>`).join(''):'<p class="text-secondary mt-3">Действий сегодня ещё не было.</p>';$('readiness').innerHTML=d.readiness.map(x=>`<div class="check-row"><span class="check-icon ${x.ready?'':'missing'}">${x.ready?'✓':'○'}</span><span class="flex-grow-1">${esc(x.label)}</span>${x.ready?'':`<button class="btn btn-sm btn-outline-primary" onclick="readinessAction('${esc(x.action)}')">${esc(x.action)}</button>`}</div>`).join('')}catch(e){showGlobal(e.message)}}
function readinessAction(action){if(action.includes('направление')||action.includes('поиск'))showSection('directions');else if(action.includes('почт'))showSection('mailboxes');else if(action.includes('Таблиц'))showSection('sheets');else showSection('settings')}

async function loadCompanies(){try{const q=new URLSearchParams({limit:'500'});if($('companyCity').value)q.set('city',$('companyCity').value);if($('companySource').value)q.set('source',$('companySource').value);companies=await api('/api/companies?'+q);const cities=[...new Set(companies.map(x=>x.city).filter(Boolean))].sort();const selected=$('companyCity').value;$('companyCity').innerHTML=optionRows(cities,'Все города');$('companyCity').value=selected;$('companyRows').innerHTML=companies.map(c=>`<tr onclick="openCompany('${c.id}')"><td>${c.website?`<a class="site-link" href="${esc(c.website)}" target="_blank" rel="noopener" onclick="event.stopPropagation()">${esc(c.website.replace(/^https?:\/\//,''))}</a>`:'—'}</td><td><strong>${esc(c.company_name)}</strong><div class="small text-secondary">${esc(c.category||'')}</div></td><td>${esc(c.city||'—')}</td><td>${esc(c.company_phone||c.phone||'—')}</td><td>${esc(c.company_email||c.email||'—')}</td><td>${esc(c.decision_maker_name||'—')}</td><td><span class="source-pill">${esc(sourceRu[c.source]||c.source)}</span></td><td><span class="state-pill ${c.manually_blocked?'off':''}">${c.manually_blocked?'Запрет отправки':'Готово'}</span></td></tr>`).join('');$('companyEmpty').classList.toggle('d-none',companies.length>0)}catch(e){showGlobal(e.message)}}
function resetCompanyFilters(){$('companyCity').value='';$('companySource').value='';loadCompanies()}$('companyCity').onchange=loadCompanies;$('companySource').onchange=loadCompanies;
async function openCompany(id){try{const d=await api(`/api/companies/${id}/details`),c=d.company,p=d.personalization_draft;$('companyDrawerTitle').textContent=c.company_name;$('companyDetails').innerHTML=`${p?`<div class="alert ${p.status==='ready'?'alert-success':'alert-warning'}"><strong>Персональное КП:</strong> ${p.delivery_id?'отправка подтверждена':p.status==='ready'?`готово к отправке <button class="btn btn-sm btn-primary ms-2" onclick="openSheetDraft('${p.id}')">Открыть предпросмотр</button>`:p.error||'идёт подготовка'}</div>`:''}<div class="d-flex gap-2 flex-wrap mb-3"><button class="btn btn-primary" onclick="openSend('${c.id}')">Отправить письмо</button><button class="btn btn-outline-primary" onclick="openPersonalized('${c.id}',this)">Подготовить персональное письмо</button>${c.website?`<button class="btn btn-outline-secondary" onclick="enrichCompany('${c.id}',this)">Дополнить данные</button><a class="btn btn-outline-primary" href="${esc(c.website)}" target="_blank" rel="noopener">Открыть сайт</a>`:''}<button class="btn btn-outline-secondary" onclick="showSection('sheets')">Открыть в Google Таблице</button></div>${infoBlock('Основная информация',[['Город',c.city],['Регион',c.region],['Адрес',c.address],['Кол-во филиалов',c.branches_count]])}${infoBlock('Контакты',[['Телефон',c.company_phone||c.phone],['Email',c.company_email||c.email]])}${infoBlock('Сайт',[['Адрес сайта',c.website]])}${infoBlock('ЛПР',[['Кто принимает решение',c.decision_maker_name],['Должность',c.decision_maker_position],['Email',c.decision_maker_email],['Телефон',c.decision_maker_phone]],'ЛПР — человек, который принимает решение о покупке.')}${infoBlock('Источники',d.sources.map(x=>[sourceRu[x.source]||x.source,x.source_url?`<a href="${esc(x.source_url)}" target="_blank" rel="noopener">Открыть карточку</a>`:'—']),null,true)}${infoBlock('История писем',d.emails.map(x=>[dateText(x.created_at),statusRu[x.status]||'Состояние неизвестно']))}<details class="mt-3"><summary>История изменений</summary><div class="small text-secondary mt-2">${d.changes.length?d.changes.map(x=>`${dateText(x.at)} — обновлено поле «${esc(x.field)}»`).join('<br>'):'Изменений пока нет.'}</div></details>`;bootstrap.Offcanvas.getOrCreateInstance($('companyDrawer')).show()}catch(e){notify(e.message,true)}}
async function enrichCompany(id,button){busy(button,true,'Ищем данные…');try{const r=await api(`/api/companies/${id}/enrich`,{method:'POST'});const labels={company_email:'Email',company_phone:'Телефон',region:'Регион',branches_count:'Количество филиалов',decision_maker_name:'ЛПР',decision_maker_position:'Должность',decision_maker_email:'Email ЛПР',decision_maker_phone:'Телефон ЛПР',inn:'ИНН'},found=(r.fields_found||[]).map(x=>labels[x]||x);notify(found.length?`Найдено: ${found.join(', ')}.`:r.deterministic?`Найдено новых полей: ${r.deterministic}.`:'Новых достоверных данных не найдено.');await openCompany(id)}catch(e){notify(e.message,true)}finally{busy(button,false)}}
function infoBlock(title,rows,hint=null,html=false){return`<div class="info-block"><h3 class="h6">${title}</h3>${hint?`<p class="small text-secondary">${hint}</p>`:''}<dl class="row simple-details mb-0">${rows.map(([a,b])=>`<dt class="col-5">${esc(a)}</dt><dd class="col-7">${html?(b||'—'):esc(b??'—')}</dd>`).join('')}</dl></div>`}

async function loadDirections(){try{directions=await api('/api/directions');$('directionCards').innerHTML=directions.map(d=>`<div class="col-md-6 col-xl-4"><div class="card direction-card"><div class="card-body"><div class="d-flex justify-content-between gap-2"><h2 class="h5">${esc(d.name)}</h2><span class="state-pill ${d.active?'':'off'}">${d.active?'Работает':'Приостановлено'}</span></div><div class="detail-label mt-3">Города</div><div>${d.locations.map(x=>esc(x.city)).join(', ')}</div><div class="detail-label mt-3">Что ищем</div><div>${d.queries.map(x=>esc(x.query)).join(', ')}</div><div class="detail-label mt-3">Источники</div><div class="d-flex gap-1 flex-wrap">${d.sources.map(x=>`<span class="source-pill">${sourceRu[x]||x}</span>`).join('')}</div><dl class="row simple-details mt-3 mb-3"><dt class="col-7">Новых за запуск</dt><dd class="col-5">${d.limit_new}</dd><dt class="col-7">Запуск</dt><dd class="col-5">${scheduleRu(d.schedule)}</dd></dl><div class="d-flex gap-2 flex-wrap"><button class="btn btn-sm btn-primary" onclick="runDirection('${d.id}',this)">Запустить сейчас</button><button class="btn btn-sm btn-outline-secondary" onclick="openDirection('${d.id}')">Редактировать</button><button class="btn btn-sm btn-light" onclick="toggleDirection('${d.id}',${d.active})">${d.active?'Приостановить':'Включить'}</button></div></div></div></div>`).join('');$('directionEmpty').classList.toggle('d-none',directions.length>0)}catch(e){showGlobal(e.message)}}
function scheduleRu(value){return value==='0 5 * * *'?'Каждый день в 10:00':value==='0 5 * * 1-5'?'По будням в 10:00':value?'По расписанию':'Вручную'}
async function runDirection(id,button){busy(button,true,'Идёт поиск…');try{await api(`/api/directions/${id}/run`,{method:'POST'});notify('Идёт поиск компаний. Результат появится здесь после завершения.')}catch(e){notify(e.message,true)}finally{busy(button,false)}}
function addQuery(value=''){const row=document.createElement('div');row.className='repeat-row';row.innerHTML=`<input class="form-control query-value" required placeholder="Например, ресторан" value="${esc(value)}"><button type="button" class="btn btn-outline-danger" aria-label="Удалить запрос">×</button>`;row.querySelector('button').onclick=()=>{row.remove();markDirty(row.closest('form'))};$('queryRows').append(row)}
function addLocation(city='',region=''){const row=document.createElement('div');row.className='repeat-row';row.innerHTML=`<input class="form-control location-city" required placeholder="Город" value="${esc(city)}"><input class="form-control location-region" placeholder="Регион" value="${esc(region)}"><button type="button" class="btn btn-outline-danger" aria-label="Удалить город">×</button>`;row.querySelector('button').onclick=()=>{row.remove();markDirty(row.closest('form'))};$('locationRows').append(row)}
function openDirection(id=''){const d=directions.find(x=>x.id===id);$('directionForm').reset();$('directionId').value=id;$('queryRows').innerHTML='';$('locationRows').innerHTML='';$('directionModalTitle').textContent=d?'Редактировать направление':'Новое направление';$('directionName').value=d?.name||'';$('sheetTab').value=d?.sheet_tab||'';$('directionLimit').value=d?.limit_new||20;$('directionSchedule').value=d?.schedule||'';$('schedulePreset').value=['','0 5 * * *','0 5 * * 1-5'].includes(d?.schedule||'')?(d?.schedule||''):'custom';(d?.queries||[{query:''}]).forEach(x=>addQuery(x.query));(d?.locations||[{city:'',region:''}]).forEach(x=>addLocation(x.city,x.region||''));$('sourceYandex').checked=!d||d.sources.includes('yandex_maps');$('source2gis').checked=!d||d.sources.includes('two_gis');$('emailEnrichment').checked=d?.email_enrichment_enabled||false;$('aiEnrichment').checked=d?.ai_enrichment_enabled||false;clearDirty();modals.direction.show()}
$('directionName').oninput=()=>{if(!$('directionId').value)$('sheetTab').value=$('directionName').value};$('schedulePreset').onchange=()=>{if($('schedulePreset').value!=='custom')$('directionSchedule').value=$('schedulePreset').value};
$('directionForm').onsubmit=async e=>{e.preventDefault();const button=$('saveDirection'),id=$('directionId').value;const payload={name:$('directionName').value.trim(),sheet_tab:$('sheetTab').value.trim(),active:id?(directions.find(x=>x.id===id)?.active??true):true,limit_new:Number($('directionLimit').value),schedule:$('directionSchedule').value.trim()||null,email_enrichment_enabled:$('emailEnrichment').checked,ai_enrichment_enabled:$('aiEnrichment').checked,queries:[...document.querySelectorAll('.query-value')].map((x,i)=>({query:x.value.trim(),active:true,priority:(i+1)*100})).filter(x=>x.query),locations:[...document.querySelectorAll('.location-city')].map((x,i)=>({city:x.value.trim(),region:document.querySelectorAll('.location-region')[i].value.trim()||null,active:true})).filter(x=>x.city),sources:[...document.querySelectorAll('.source-check:checked')].map(x=>x.value)};if(!payload.queries.length||!payload.locations.length||!payload.sources.length){notify('Добавьте запрос, город и хотя бы один источник.',true);return}busy(button,true,'Сохраняем…');try{await api(id?`/api/directions/${id}`:'/api/directions',{method:id?'PATCH':'POST',body:JSON.stringify(payload)});clearDirty();modals.direction.hide();notify('Изменения сохранены');loadDirections()}catch(error){notify(error.message,true)}finally{busy(button,false)}};
function toggleDirection(id,active){const d=directions.find(x=>x.id===id),verb=active?'Приостановить':'Включить';confirmAction(`${verb} направление «${d.name}»?`,active?'Найденные ранее компании останутся в системе.':'Поиск снова будет доступен.',verb,async()=>{await api(`/api/directions/${id}`,{method:'PATCH',body:JSON.stringify({active:!active})});notify(active?'Направление приостановлено.':'Направление включено.');loadDirections()})}

async function loadLetters(){try{[deliveries,analyticsData]=await Promise.all([api('/api/deliveries?limit=500'),api('/api/analytics')]);const e=analyticsData.email;$('emailSummary').innerHTML=[['В очереди',e.queued],['Отправлено',e.sent],['Открыто',e.opened],['Ответили',e.replied],['Не доставлено',e.bounced],['Отписались',e.unsubscribed]].map(x=>metric(...x)).join('');$('deliveryRows').innerHTML=deliveries.map(x=>`<tr><td>${dateText(x.created_at)}</td><td>${esc(x.recipient_email)}</td><td>${esc(x.subject)}</td><td>${x.send_mode==='manual'?'Вручную':'Автоматически'}</td><td><span class="state-pill ${['failed','send_error','bounced'].includes(x.status)?'off':''}">${statusRu[x.status]||'Обрабатывается'}</span></td></tr>`).join('');$('deliveryEmpty').classList.toggle('d-none',deliveries.length>0)}catch(e){showGlobal(e.message)}}

async function loadMailboxes(){try{[mailboxes,analyticsData]=await Promise.all([api('/api/mail-accounts'),api('/api/analytics')]);const stats=new Map(analyticsData.mailboxes.map(x=>[x.id,x]));$('mailboxCards').innerHTML=mailboxes.map(x=>{const s=stats.get(x.id)||{};return`<div class="col-md-6 col-xl-4"><div class="card direction-card"><div class="card-body"><div class="eyebrow">${esc(x.name)}</div><h2 class="h5 mt-2">${esc(x.from_email)}</h2><span class="state-pill ${x.active?'':'off'}">${x.active?'Подключено':'Отключено'}</span><p class="mt-3 mb-1">Сегодня: <strong>${s.sent||0} из ${x.daily_limit} писем</strong></p><p class="small text-secondary">Ответов: ${s.replies||0} · Ошибок: ${s.errors||0}</p><div class="d-flex gap-2 flex-wrap"><button class="btn btn-sm btn-primary" onclick="testMail('${x.id}',this)">Проверить подключение</button><button class="btn btn-sm btn-outline-secondary" onclick="openMailbox('${x.id}')">Редактировать</button><button class="btn btn-sm btn-light" onclick="toggleMailbox('${x.id}',${x.active})">${x.active?'Отключить':'Включить'}</button></div></div></div></div>`}).join('');$('mailboxEmpty').classList.toggle('d-none',mailboxes.length>0)}catch(e){showGlobal(e.message)}}
function mailSettings(email){const domain=(email.split('@')[1]||'').toLowerCase();const known={'yandex.ru':['smtp.yandex.ru','imap.yandex.ru'],'ya.ru':['smtp.yandex.ru','imap.yandex.ru'],'mail.ru':['smtp.mail.ru','imap.mail.ru'],'gmail.com':['smtp.gmail.com','imap.gmail.com']};return known[domain]||['','']}
$('mailboxEmail').onblur=()=>{const [smtp,imap]=mailSettings($('mailboxEmail').value);if(!$('smtpHost').value)$('smtpHost').value=smtp;if(!$('imapHost').value)$('imapHost').value=imap;if(!$('smtpLogin').value)$('smtpLogin').value=$('mailboxEmail').value;if(!$('imapLogin').value)$('imapLogin').value=$('mailboxEmail').value};
function openMailbox(id=''){const x=mailboxes.find(v=>v.id===id);$('mailboxForm').reset();$('mailboxId').value=id;$('mailboxName').value=x?.name||'';$('mailboxEmail').value=x?.from_email||'';$('senderName').value=x?.from_name||'';$('mailDailyLimit').value=x?.daily_limit||100;$('mailActive').checked=x?.active??true;$('smtpHost').value=x?.smtp_host||'';$('smtpPort').value=x?.smtp_port||465;$('smtpSecurity').value=x?.smtp_security||'ssl';$('smtpLogin').value=x?.smtp_login||'';$('imapHost').value=x?.imap_host||'';$('imapPort').value=x?.imap_port||993;$('imapSecurity').value=x?.imap_security||'ssl';$('imapLogin').value=x?.imap_login||'';clearDirty();modals.mailbox.show()}
$('mailboxForm').onsubmit=async e=>{e.preventDefault();const id=$('mailboxId').value,password=$('mailPassword').value,p={name:$('mailboxName').value,from_email:$('mailboxEmail').value,from_name:$('senderName').value||null,daily_limit:Number($('mailDailyLimit').value),active:$('mailActive').checked,smtp_host:$('smtpHost').value,smtp_port:Number($('smtpPort').value),smtp_security:$('smtpSecurity').value,smtp_login:$('smtpLogin').value,imap_host:$('imapHost').value,imap_port:Number($('imapPort').value),imap_security:$('imapSecurity').value,imap_login:$('imapLogin').value};if(password){p.smtp_password=password;p.imap_password=password}if(!id&&!password){notify('Укажите пароль приложения.',true);return}try{await api(id?`/api/mail-accounts/${id}`:'/api/mail-accounts',{method:id?'PATCH':'POST',body:JSON.stringify(p)});clearDirty();modals.mailbox.hide();notify('Изменения сохранены');loadMailboxes()}catch(error){notify(error.message,true)}};
async function testMail(id,button){busy(button,true,'Проверяем…');try{const r=await api(`/api/mail-accounts/${id}/test`,{method:'POST'});if(r.smtp.authentication&&r.imap.authentication)notify('Почта подключена и работает.');else notify(!r.smtp.authentication?'Не удалось войти в почту. Проверьте адрес и пароль приложения.':'Не удалось проверить входящие письма.',true)}catch(e){notify(e.message,true)}finally{busy(button,false)}}
function toggleMailbox(id,active){const x=mailboxes.find(v=>v.id===id);confirmAction(`${active?'Отключить':'Включить'} почтовый ящик «${x.name}»?`,active?'Новые письма с него отправляться не будут.':'Почтовый ящик снова будет доступен.',active?'Отключить':'Включить',async()=>{await api(`/api/mail-accounts/${id}`,{method:'PATCH',body:JSON.stringify({active:!active})});notify(active?'Почтовый ящик отключён.':'Почтовый ящик включён.');loadMailboxes()})}

async function loadTemplates(){try{templates=await api('/api/templates');$('templateCards').innerHTML=templates.map(x=>`<div class="col-md-6 col-xl-4"><div class="card direction-card"><div class="card-body"><div class="d-flex justify-content-between"><h2 class="h5">${esc(x.name)}</h2><span class="state-pill ${x.active?'':'off'}">${x.active?'Используется':'Отключён'}</span></div><div class="detail-label mt-3">Тема письма</div><p>${esc(x.subject_template)}</p><div class="detail-label">Направление</div><p>${esc(directions.find(d=>d.id===x.direction_id)?.name||'Для всех направлений')}</p><button class="btn btn-sm btn-primary" onclick="openTemplate('${x.id}')">Редактировать</button></div></div></div>`).join('');$('templateEmpty').classList.toggle('d-none',templates.length>0)}catch(e){showGlobal(e.message)}}
function openTemplate(id=''){const x=templates.find(v=>v.id===id);$('templateForm').reset();$('templateId').value=id;$('templateDirection').innerHTML=optionRows(directions,'Для всех направлений');$('templateName').value=x?.name||'';$('templateDirection').value=x?.direction_id||'';$('templateSubject').value=x?.subject_template||'';$('templateText').value=x?.text_template||stripHtml(x?.html_template||'');$('templateHtml').value=x?.html_template||'';updateTemplatePreview();clearDirty();modals.template.show()}
function stripHtml(value){const d=document.createElement('div');d.innerHTML=value;return d.textContent||''}function textToHtml(value){return value.split(/\n{2,}/).map(x=>`<p>${esc(x).replace(/\n/g,'<br>')}</p>`).join('')}
function updateTemplatePreview(){let value=$('templateText').value||'Начните вводить текст письма.';value=value.replaceAll('{{ company_name }}','ООО «Ромашка»').replaceAll('{{ city }}','Москва').replaceAll('{{ decision_maker_name }}','Иван').replaceAll('{{ sender_name }}','Анна');$('templatePreview').textContent=value}$('templateText').oninput=updateTemplatePreview;
document.querySelectorAll('.insert-field').forEach(x=>x.onclick=()=>{const t=$('templateText'),field=`{{ ${x.dataset.field} }}`,start=t.selectionStart;t.value=t.value.slice(0,start)+field+t.value.slice(t.selectionEnd);t.focus();t.selectionStart=t.selectionEnd=start+field.length;updateTemplatePreview();markDirty(t.closest('form'))});
$('templateForm').onsubmit=async e=>{e.preventDefault();const id=$('templateId').value,text=$('templateText').value,p={name:$('templateName').value,direction_id:$('templateDirection').value||null,category:null,subject_template:$('templateSubject').value,text_template:text,html_template:$('templateHtml').value||textToHtml(text),active:true};try{await api(id?`/api/templates/${id}`:'/api/templates',{method:id?'PATCH':'POST',body:JSON.stringify(p)});clearDirty();modals.template.hide();notify('Изменения сохранены');loadTemplates()}catch(error){notify(error.message,true)}};
async function sendTemplateTest(){if(!companies.length)companies=await api('/api/companies?limit=500');const x=companies.find(c=>c.company_email||c.email||c.decision_maker_email);if(!x){notify('Сначала добавьте компанию с email.',true);return}modals.template.hide();await openSend(x.id,$('templateId').value)}

async function openSend(companyId,templateId=''){await loadBase();const c=companies.find(x=>x.id===companyId)||await api('/api/companies?limit=500').then(xs=>xs.find(x=>x.id===companyId));if(!c){notify('Компания не найдена.',true);return}$('sendRequestKey').value='';$('sendDraftId').value='';$('sendModalTitle').textContent='Отправить письмо';$('personalizationFacts').classList.add('d-none');$('sendCompany').value=c.id;$('sendRecipient').textContent=`${c.company_name} — ${c.decision_maker_email||c.company_email||c.email||'email не указан'}`;$('sendMailbox').innerHTML=mailboxes.filter(x=>x.active).map(x=>`<option value="${x.id}">${esc(x.name)} — ${esc(x.from_email)}</option>`).join('');$('sendTemplate').innerHTML=templates.filter(x=>x.active).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');if(templateId)$('sendTemplate').value=templateId;await previewSend();modals.send.show()}
async function openSheetDraft(draftId){try{await loadBase();const p=await api(`/api/personalization-drafts/${draftId}`),c=companies.find(x=>x.id===p.company_id)||await api('/api/companies?limit=500').then(xs=>xs.find(x=>x.id===p.company_id));if(!c||p.status!=='ready')throw Error('Персональное письмо ещё не готово.');$('sendCompany').value=c.id;$('sendDraftId').value=p.id;$('sendRequestKey').value=p.request_key||'sheet';$('sendRecipient').textContent=`${c.company_name} — ${c.decision_maker_email||c.company_email||c.email||'email не указан'}`;$('sendMailbox').innerHTML=mailboxes.filter(x=>x.active).map(x=>`<option value="${x.id}">${esc(x.name)} — ${esc(x.from_email)}</option>`).join('');$('sendTemplate').innerHTML=templates.filter(x=>x.active).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');$('sendMailbox').value=p.mailbox_id;$('sendTemplate').value=p.template_id;$('sendMailbox').disabled=true;$('sendTemplate').disabled=true;$('sendModalTitle').textContent='Персональное КП — проверьте перед отправкой';$('sendSubject').value=p.subject;$('sendText').value=p.text_body;$('sendInitialText').value=p.text_body;$('sendHtml').value=p.html_body;$('personalizationFacts').innerHTML=`<div class="alert alert-light mb-0"><strong>Использованные факты:</strong><ul class="mb-0">${(p.facts||[]).map(x=>`<li>${esc(x.text)}</li>`).join('')||'<li>Нейтральное обращение без догадок</li>'}</ul></div>`;$('personalizationFacts').classList.remove('d-none');modals.send.show()}catch(e){notify(e.message,true)}}
async function openPersonalized(companyId,button){busy(button,true,'Анализируем сайт…');try{await openSend(companyId);if(!$('sendTemplate').value)throw Error('Сначала создайте шаблон письма.');const r=await api(`/api/companies/${companyId}/personalization-preview`,{method:'POST',body:JSON.stringify({template_id:$('sendTemplate').value,mailbox_id:$('sendMailbox').value||null})});$('sendRequestKey').value=r.request_key;$('sendModalTitle').textContent='Персональное письмо — предпросмотр';$('sendSubject').value=r.subject;$('sendText').value=r.text_body||stripHtml(r.html_body);$('sendInitialText').value=$('sendText').value;$('sendHtml').value=r.html_body;$('personalizationFacts').innerHTML=`<div class="alert alert-light mb-0"><strong>Использованные факты:</strong><ul class="mb-0">${(r.facts||[]).map(x=>`<li>${esc(x.text)}</li>`).join('')||'<li>Нейтральное обращение без догадок</li>'}</ul></div>`;$('personalizationFacts').classList.remove('d-none');notify(r.cache_hit?'Использован сохранённый вариант.':'Персональное письмо подготовлено. Проверьте его перед отправкой.')}catch(e){modals.send.hide();notify(e.message,true)}finally{busy(button,false)}}
async function previewSend(){const company=$('sendCompany').value,template=$('sendTemplate').value;if(!company||!template)return;$('sendRequestKey').value='';$('sendModalTitle').textContent='Отправить письмо';$('personalizationFacts').classList.add('d-none');try{const r=await api(`/api/templates/${template}/preview`,{method:'POST',body:JSON.stringify({company_id:company})});$('sendSubject').value=r.subject;$('sendText').value=r.text_body||stripHtml(r.html_body);$('sendInitialText').value=$('sendText').value;$('sendHtml').value=r.html_body}catch(e){notify(e.message,true)}}$('sendTemplate').onchange=previewSend;
$('sendForm').onsubmit=async e=>{e.preventDefault();const button=e.submitter;busy(button,true,'Отправляем…');const key=$('sendRequestKey').value,draft=$('sendDraftId').value,currentText=$('sendText').value,p={mailbox_id:$('sendMailbox').value,template_id:$('sendTemplate').value,subject:$('sendSubject').value,text_body:currentText,html_body:currentText===$('sendInitialText').value?$('sendHtml').value:textToHtml(currentText),request_key:key||'manual'};try{const path=draft?`/api/personalization-drafts/${draft}/send`:`/api/companies/${$('sendCompany').value}/${key?'send-personalized':'send'}`;if(!key&&!draft)delete p.request_key;await api(path,{method:'POST',body:JSON.stringify(p)});modals.send.hide();notify('Письмо поставлено в очередь на отправку.')}catch(error){notify(error.message,true)}finally{busy(button,false)}};$('sendModal').addEventListener('hidden.bs.modal',()=>{$('sendMailbox').disabled=false;$('sendTemplate').disabled=false});

async function loadSheets(){try{const s=await api('/api/google-sheets/status');$('sheetState').textContent=s.configured?'Подключена':'Не подключена';$('sheetBadge').textContent=s.configured?'Работает':'Нужна настройка';$('sheetBadge').classList.toggle('off',!s.configured);$('sheetLast').textContent=dateText(s.last_sync_at);$('sheetMapped').textContent=s.mapped_rows||0;$('sheetHint').textContent=s.configured?'Компании синхронизируются по направлениям.':'Подключите таблицу в настройках.';$('openSheet').href=s.spreadsheet_url||'#';$('openSheet').classList.toggle('disabled',!s.spreadsheet_url);$('sheetAccessHelp').classList.toggle('d-none',s.configured);if(!s.configured)$('sheetAccessHelp').textContent=s.service_account_email?`Предоставьте доступ к таблице адресу ${s.service_account_email}.`:'Добавьте сервисный адрес в настройках. Закрытый ключ никогда не показывается в интерфейсе.'}catch(e){$('sheetState').textContent='Нет доступа к Google Таблице';$('sheetAccessHelp').textContent=e.message;$('sheetAccessHelp').classList.remove('d-none')}}
async function syncAll(button){busy(button,true,'Синхронизация…');try{const configs=await api('/api/google-sheets');if(!configs.length)throw Error('Google Таблица не настроена.');const r=await api(`/api/google-sheets/${configs[0].id}/sync`,{method:'POST'});notify(`Готово: добавлено ${r.inserted}, обновлено ${r.updated}.`);loadSheets()}catch(e){notify(e.message,true)}finally{busy(button,false)}}async function testSheets(button){busy(button,true,'Проверяем…');try{await api('/api/google-sheets/test',{method:'POST'});notify('Google Таблица подключена.')}catch(e){notify(e.message,true)}finally{busy(button,false)}}

function todayIso(){const d=new Date();d.setHours(0,0,0,0);return d.toISOString()}function analyticsQuery(){const q=new URLSearchParams();let from=new Date();if(periodDays===0)from.setHours(0,0,0,0);else if(Number.isFinite(periodDays))from.setDate(from.getDate()-periodDays);else if($('dateFrom').value)from=new Date($('dateFrom').value+'T00:00:00');q.set('date_from',from.toISOString());if(periodDays==='custom'&&$('dateTo').value)q.set('date_to',new Date($('dateTo').value+'T23:59:59').toISOString());[['filterDirection','direction'],['filterCity','city'],['filterSource','source'],['filterMailbox','mailbox'],['filterTemplate','template']].forEach(([id,key])=>{if($(id).value)q.set(key,$(id).value)});return q}
async function loadAnalytics(){if(currentAnalyticsTab==='ai')return loadAIUsage();try{$('analyticsBody').innerHTML='<div class="loading-block"><div class="spinner-border text-primary"></div><span>Собираем данные…</span></div>';analyticsData=await api('/api/analytics?'+analyticsQuery());fillAnalyticsFilters(analyticsData.filter_options);renderAnalytics()}catch(e){$('analyticsBody').innerHTML=empty(e.message,'Попробуйте обновить страницу.')}}
function fillAnalyticsFilters(o){const defs=[['filterDirection',o.directions,'Все направления'],['filterCity',o.cities,'Все города'],['filterSource',o.sources,'Все источники'],['filterMailbox',o.mailboxes,'Все почтовые ящики'],['filterTemplate',o.templates,'Все шаблоны']];defs.forEach(([id,items,label])=>{const old=$(id).value;$(id).innerHTML=optionRows(items,label);$(id).value=old})}
function renderAnalytics(){const d=analyticsData;if(currentAnalyticsTab==='overview')renderOverview(d);if(currentAnalyticsTab==='search')renderSearch(d);if(currentAnalyticsTab==='companies')renderCompanyAnalytics(d);if(currentAnalyticsTab==='email')renderEmailAnalytics(d);if(currentAnalyticsTab==='replies')renderReplies(d);if(currentAnalyticsTab==='sources')renderSources(d);if(currentAnalyticsTab==='sheets')renderSheetAnalytics(d);if(currentAnalyticsTab==='system')renderSystem(d);if(currentAnalyticsTab==='ai'&&aiUsageData)renderAIUsage();const ai=currentAnalyticsTab==='ai';document.querySelectorAll('.general-filter').forEach(x=>x.classList.toggle('d-none',ai));document.querySelectorAll('.email-filter').forEach(x=>x.classList.toggle('d-none',ai||!['overview','email','replies'].includes(currentAnalyticsTab)))}
function renderOverview(d){const o=d.overview,a=d.ai||{};$('analyticsBody').innerHTML=`<div class="row g-3 mb-4">${[['Найдено компаний',o.found],['Новых уникальных',o.new],['Дубликатов',o.duplicates],['Компаний с сайтом',o.with_website],['Компаний с email',o.with_email],['Компаний с телефоном',o.with_phone],['Компаний с ЛПР',o.with_decision_maker],['Отправлено писем',o.sent],['Открыто',o.opened],['Переходов',o.clicked],['Ответов',o.replied],['Не доставлено',o.bounced],['Отписок',o.unsubscribed]].map(x=>metric(...x)).join('')}</div><div class="row g-3"><div class="col-lg-7">${chart('Новые компании по дням',d.daily.map(x=>({name:new Date(x.date).toLocaleDateString('ru-RU',{day:'numeric',month:'short'}),value:x.new})))}</div><div class="col-lg-5"><div class="chart-card"><h3 class="h5">Воронка</h3>${d.funnel.map((x,i)=>`<div class="funnel-row" style="width:${Math.max(48,100-i*11)}%">${x.label}: ${x.value}</div>`).join('')}</div></div><div class="col-12">${chart('Отправленные письма и ответы',d.daily.map(x=>({name:new Date(x.date).toLocaleDateString('ru-RU',{day:'numeric',month:'short'}),value:x.sent,label:`${new Date(x.date).toLocaleDateString('ru-RU',{day:'numeric',month:'short'})} · ответов ${x.replied}`})))}</div><div class="col-12"><div class="chart-card"><h3 class="h5">ИИ</h3><div class="row g-3">${[['Запросов к ИИ',a.requests],['Компаний дополнено',a.companies_enriched],['Найдено ЛПР',a.decision_makers_found],['Дополнено email',a.emails_added],['Дополнено телефонов',a.phones_added],['Подготовлено писем',a.personalized_emails],['Входных токенов',a.input_tokens],['Выходных токенов',a.output_tokens],['Ориентировочная стоимость, $',a.estimated_cost]].map(x=>metric(...x)).join('')}</div></div></div></div>`}
async function loadAIUsage(offset=0){aiUsageOffset=Math.max(0,offset);$('analyticsBody').innerHTML='<div class="loading-block"><div class="spinner-border text-primary"></div><span>Собираем журнал расходов…</span></div>';try{const period=analyticsQuery(),q=new URLSearchParams({limit:'50',offset:String(aiUsageOffset)});if(period.get('date_from'))q.set('date_from',period.get('date_from'));if(period.get('date_to'))q.set('date_to',period.get('date_to'));if(aiCompanyFilter)q.set('company_id',aiCompanyFilter);if(aiOperationFilter)q.set('operation',aiOperationFilter);aiUsageData=await api('/api/analytics/ai-usage?'+q);renderAnalytics()}catch(e){$('analyticsBody').innerHTML=empty(e.message,'Попробуйте обновить страницу.')}}
function aiSummaryCard(label,item){return`<div class="col-6 col-lg-3"><div class="metric-card"><div class="metric-label">Потрачено ${esc(label)}</div><div class="metric-value ai-cost">${money(item.cost)}</div><div class="small text-secondary mt-1">Запросов: ${item.requests}</div></div></div>`}
function renderAIUsage(){const d=aiUsageData,s=d.summary,from=aiUsageOffset+1,to=Math.min(aiUsageOffset+d.rows.length,d.total);$('analyticsBody').innerHTML=`<div class="row g-3 mb-4">${aiSummaryCard('сегодня',s.today)}${aiSummaryCard('за 7 дней',s.seven_days)}${aiSummaryCard('за 30 дней',s.thirty_days)}${aiSummaryCard('за всё время',s.all)}</div><div class="row g-3 mb-4">${d.breakdown.map(x=>`<div class="col-md-4"><div class="chart-card"><div class="metric-label">${esc(x.label)}</div><div class="h4 mt-2 mb-1">${money(x.cost)}</div><div class="small text-secondary">Запросов за выбранный период: ${x.requests}</div></div></div>`).join('')}</div><div class="filter-card mb-3"><div class="row g-2"><div class="col-md-5"><label class="form-label">Компания</label><select class="form-select" id="aiCompanyFilter" onchange="setAICompany(this.value)">${optionRows(d.companies,'Все компании')}</select></div><div class="col-md-5"><label class="form-label">Тип операции</label><select class="form-select" id="aiOperationFilter" onchange="setAIOperation(this.value)">${optionRows(d.operations,'Все операции')}</select></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-outline-secondary w-100" onclick="resetAIFilters()">Сбросить</button></div></div></div><div class="chart-card"><div class="d-flex flex-wrap justify-content-between gap-2 align-items-center mb-3"><div><h3 class="h5 mb-1">Журнал расходов DeepSeek</h3><div class="small text-secondary">Каждая строка — один вызов или использование сохранённого результата.</div></div><div class="small text-secondary">${d.total?`Показано ${from}–${to} из ${d.total}`:'Записей нет'}</div></div>${d.rows.length?`<div class="table-responsive"><table class="table align-middle ai-usage-table"><thead><tr><th>Дата и время</th><th>Компания / сайт</th><th>Тип задачи</th><th>Искали</th><th>Результат</th><th>Input</th><th>Cached</th><th>Output</th><th>Reasoning</th><th>Модель</th><th>Стоимость</th><th>Статус</th></tr></thead><tbody>${d.rows.map(x=>`<tr tabindex="0" role="button" onclick="openAIUsage('${x.id}')" onkeydown="if(event.key==='Enter')openAIUsage('${x.id}')"><td>${dateText(x.created_at)}</td><td><strong>${esc(x.company)}</strong>${x.website?`<div class="small text-secondary ai-site">${esc(x.website.replace(/^https?:\/\//,''))}</div>`:''}</td><td>${esc(x.operation_label)}</td><td>${esc(x.fields.join(', ')||'—')}</td><td>${esc(x.result)}</td><td>${x.input_tokens}</td><td>${x.cached_input_tokens}</td><td>${x.output_tokens}</td><td>${x.reasoning_tokens}</td><td>${esc(x.model)}</td><td>${money(x.estimated_cost)}</td><td><span class="state-pill ai-status-${x.status}">${esc(x.status_label)}</span></td></tr>`).join('')}</tbody></table></div><div class="d-flex justify-content-between mt-3"><button class="btn btn-sm btn-outline-secondary" ${aiUsageOffset?'':'disabled'} onclick="loadAIUsage(${Math.max(0,aiUsageOffset-50)})">Назад</button><button class="btn btn-sm btn-outline-secondary" ${to<d.total?'':'disabled'} onclick="loadAIUsage(${aiUsageOffset+50})">Далее</button></div>`:empty('За выбранный период обращений к ИИ не было.','Выберите более длинный период или сбросьте фильтры.')}</div>`;$('aiCompanyFilter').value=aiCompanyFilter;$('aiOperationFilter').value=aiOperationFilter}
function setAICompany(value){aiCompanyFilter=value;loadAIUsage(0)}function setAIOperation(value){aiOperationFilter=value;loadAIUsage(0)}function resetAIFilters(){aiCompanyFilter='';aiOperationFilter='';loadAIUsage(0)}
async function openAIUsage(id){$('aiUsageTitle').textContent='Детали запроса';$('aiUsageDetails').innerHTML='<div class="loading-block"><div class="spinner-border text-primary"></div><span>Загружаем детали…</span></div>';modals.aiUsage.show();try{const d=await api(`/api/analytics/ai-usage/${id}`);$('aiUsageTitle').textContent=`${d.operation_label} · ${d.company}`;const context=d.website_context.length?d.website_context.map(x=>`<div class="ai-context-block"><div class="small mb-2">${publicLink(x.source_url,x.source_url)}</div><div>${esc(x.text)}</div></div>`).join(''):`<div class="alert alert-light mb-0">${d.operation==='connection_test'?'Для проверки подключения данные сайта не использовались.':d.context_available?'Полезные факты сайта не были найдены.':'Сохранённый контекст сайта изменился или недоступен.'}</div>`;const found=d.found_values.length?d.found_values.map(x=>`<div class="info-block"><strong>${esc(x.label)}:</strong> ${esc(x.value)}<div class="small text-secondary mt-1">${esc(x.evidence_text||'Подтверждающий фрагмент не сохранён.')}</div><div class="small mt-1">${publicLink(x.source_url)}</div></div>`).join(''):'<p class="text-secondary mb-0">Новых подтверждённых значений не получено.</p>';const personalized=d.personalization?`<dl class="row simple-details mb-0"><dt class="col-sm-3">Тема</dt><dd class="col-sm-9">${esc(d.personalization.subject||'—')}</dd><dt class="col-sm-3">Вступление</dt><dd class="col-sm-9">${esc(d.personalization.intro||'—')}</dd><dt class="col-sm-3">Персональный абзац</dt><dd class="col-sm-9">${esc(d.personalization.personalized_paragraph||'—')}</dd></dl>`:'';$('aiUsageDetails').innerHTML=`<div class="row g-3 mb-3"><div class="col-md-6">${infoBlock('Запрос',[['Дата и время',dateText(d.created_at)],['Компания',d.company],['Сайт',d.website],['Тип задачи',d.operation_label],['Статус',d.status_label]])}</div><div class="col-md-6"><div class="chart-card"><h3 class="h6">Токены и стоимость</h3><dl class="row simple-details mb-0"><dt class="col-7">Входные токены</dt><dd class="col-5">${d.input_tokens}</dd><dt class="col-7">Из кэша провайдера</dt><dd class="col-5">${d.cached_input_tokens}</dd><dt class="col-7">Выходные токены</dt><dd class="col-5">${d.output_tokens}</dd><dt class="col-7">Токены рассуждений</dt><dd class="col-5">${d.reasoning_tokens}</dd><dt class="col-7">Модель</dt><dd class="col-5">${esc(d.model)}</dd><dt class="col-7">Стоимость запроса</dt><dd class="col-5">${money(d.estimated_cost)}</dd></dl></div></div></div><div class="chart-card mb-3"><h3 class="h6">Почему вызван ИИ</h3><p class="mb-0">${esc(d.reason)}</p></div>${personalized?`<div class="chart-card mb-3"><h3 class="h6">Созданные фрагменты письма</h3>${personalized}</div>`:''}<div class="chart-card mb-3"><h3 class="h6">Найденные значения и подтверждения</h3>${found}</div><div class="chart-card"><h3 class="h6">Какие данные сайта использованы</h3>${context}</div>`}catch(e){$('aiUsageDetails').innerHTML=empty(e.message,'Закройте окно и попробуйте ещё раз.')}}
function tableCard(title,headers,rows){return`<div class="chart-card mb-3"><h3 class="h5">${esc(title)}</h3>${rows.length?`<div class="table-responsive"><table class="table align-middle"><thead><tr>${headers.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`:empty('За выбранный период данных пока нет.')}</div>`}
function renderSearch(d){const s=d.search;$('analyticsBody').innerHTML=`<div class="row g-3 mb-4">${[['Всего запусков',s.runs],['Успешных запусков',s.successful],['Запусков с ошибкой',s.failed],['Найдено карточек',s.observations],['Новых компаний',s.new],['Дубликатов',s.duplicates]].map(x=>metric(...x)).join('')}</div>${s.last_error?`<div class="alert alert-warning">${esc(s.last_error)}</div>`:''}${tableCard('По направлениям',['Направление','Найдено','Новых','Дубликатов','Ошибок','Последний запуск'],s.directions.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td>${x.observations}</td><td>${x.new}</td><td>${x.duplicates}</td><td>${x.errors}</td><td>${dateText(x.last_run)}</td></tr>`))}<div class="row g-3"><div class="col-lg-6">${analyticsTable('Эффективность поисковых запросов',d.queries)}</div><div class="col-lg-6">${analyticsTable('Результаты по городам',d.cities)}</div></div>${s.errors.length?tableCard('Ошибки поиска',['Время','Источник','Что произошло'],s.errors.map(x=>`<tr><td>${dateText(x.at)}</td><td>${esc(x.source)}</td><td>${esc(x.message)}</td></tr>`)):''}`}
function analyticsTable(title,rows){return tableCard(title,['Название','Найдено','Новых','Дубликатов','Уникальность'],rows.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td>${x.observations}</td><td>${x.new_companies}</td><td>${x.duplicates}</td><td>${x.unique_rate}%</td></tr>`))}
function renderCompanyAnalytics(d){const b=d.branches,w=d.websites;$('analyticsBody').innerHTML=`<div class="row g-3 mb-3"><div class="col-lg-7"><div class="chart-card"><h3 class="h5">Заполненность контактных данных</h3><p class="text-secondary">Всего компаний: ${d.data_quality.total}</p>${d.data_quality.fields.map(x=>`<div class="quality-row"><span>${esc(x.label)}</span><div class="bar-track"><div class="bar-fill" style="width:${x.percent}%"></div></div><strong>${x.percent}%</strong></div>`).join('')}</div></div><div class="col-lg-5"><div class="chart-card"><h3 class="h5">Количество филиалов</h3><p>Известно: <strong>${b.known}</strong></p><p>Нет данных: <strong>${b.unknown}</strong></p><p>Среднее количество: <strong>${b.average}</strong></p><p>Сетей с более чем одним филиалом: <strong>${b.networks}</strong></p><hr><h3 class="h5">Сайты компаний</h3><p>С сайтом: <strong>${w.known}</strong></p><p>Без сайта: <strong>${w.unknown}</strong></p><p>Покрытие: <strong>${w.coverage}%</strong></p></div></div></div>`}
function renderEmailAnalytics(d){const e=d.email;$('analyticsBody').innerHTML=`<div class="row g-3 mb-4">${[['Поставлено в очередь',e.queued],['Отправлено',e.sent],['Ошибок отправки',e.errors],['Открыто',e.opened],['Переходов',e.clicked],['Ответов',e.replied],['Не доставлено',e.bounced],['Отписок',e.unsubscribed]].map(x=>metric(...x)).join('')}</div><div class="alert alert-info">Открытия определяются приблизительно и могут учитываться не всеми почтовыми программами.</div><div class="row g-3"><div class="col-lg-5">${chart('Показатели писем',Object.entries(e.rates).map(([k,v])=>({name:{delivery:'Доставлено',open:'Открыто',click:'Перешли',reply:'Ответили',bounce:'Не доставлено',unsubscribe:'Отписались'}[k],value:v})))}</div><div class="col-lg-7">${tableCard('По почтовым ящикам',['Ящик','Отправлено','Лимит','Ответов','Ошибок'],d.mailboxes.map(x=>`<tr><td><strong>${esc(x.name)}</strong><div class="small text-secondary">${esc(x.email)}</div></td><td>${x.sent}</td><td>${x.daily_limit}</td><td>${x.replies}</td><td>${x.errors}</td></tr>`))}</div><div class="col-12">${tableCard('По шаблонам',['Шаблон','Отправлено','Открыто','Переходов','Ответов','Не доставлено','Отписок'],d.templates.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td>${x.sent}</td><td>${x.opened}</td><td>${x.clicked}</td><td>${x.replied}</td><td>${x.bounced}</td><td>${x.unsubscribed}</td></tr>`))}</div></div>`}
function renderReplies(d){$('analyticsBody').innerHTML=`<div class="row g-3 mb-4">${metric('Получено ответов',d.replies.total)}</div>${tableCard('Последние ответы',['Компания','Дата','Направление','Письмо','Почтовый ящик'],d.replies.rows.map(x=>`<tr><td><strong>${esc(x.company)}</strong></td><td>${dateText(x.date)}</td><td>${esc(x.direction||'—')}</td><td>${esc(x.subject)}</td><td>${esc(x.mailbox)}</td></tr>`))}`}
function renderSources(d){$('analyticsBody').innerHTML=`${d.sources.insights.map(x=>`<div class="alert alert-success">${esc(x)}</div>`).join('')}${tableCard('Яндекс Карты и 2ГИС',['Источник','Карточек','Новых','Дубликатов','Телефонов','Email','Сайтов','С филиалами','Ошибок','Средний ответ'],d.sources.rows.map(x=>`<tr><td><strong>${esc(x.label)}</strong></td><td>${x.observations}</td><td>${x.new_companies}</td><td>${x.duplicates}</td><td>${x.with_phone}</td><td>${x.with_email}</td><td>${x.with_website}</td><td>${x.with_branches_count}</td><td>${x.errors}</td><td>${x.average_response_ms} мс</td></tr>`))}`}
function renderSheetAnalytics(d){const s=d.sheets;$('analyticsBody').innerHTML=`<div class="alert ${s.errors?'alert-warning':'alert-success'}">${s.errors?'Последняя синхронизация завершилась с ошибкой.':'Google Таблица синхронизируется нормально.'}</div><div class="row g-3">${[['Строк добавлено',s.inserted],['Строк обновлено',s.updated],['Пропущено',s.skipped],['Ручных изменений получено',s.manual_changes],['Конфликтов',s.conflicts],['Ошибок',s.errors]].map(x=>metric(...x)).join('')}</div><div class="chart-card mt-3"><p><strong>Последняя успешная синхронизация:</strong> ${dateText(s.last_success)}</p>${s.last_error?`<p class="text-danger">${esc(s.last_error)}</p>`:''}</div>`}
function renderSystem(d){$('analyticsBody').innerHTML=d.system.map(x=>`<div class="health-row"><div class="d-flex justify-content-between gap-2"><div><span class="status-dot bg-${x.status==='Работает'?'success':'warning'}"></span><span class="health-name">${esc(x.name)}</span></div><span class="state-pill ${x.status==='Работает'?'':'off'}">${esc(x.status)}</span></div><div class="small text-secondary mt-2">Последняя успешная операция: ${dateText(x.last_success)} · Ошибок за 24 часа: ${x.errors_24h}</div>${x.problem?`<div class="mt-2"><strong>Что произошло:</strong> ${esc(x.problem)} <button class="btn btn-sm btn-outline-primary ms-2">${esc(x.action)}</button></div>`:''}<details class="mt-2"><summary class="small">Технические подробности</summary><div class="technical mt-2">Время проверки: ${new Date().toISOString()}\nОшибок за 24 часа: ${x.errors_24h}\nСекретные данные скрыты.</div></details></div>`).join('')}
document.querySelectorAll('#analyticsTabs .nav-link').forEach(x=>x.onclick=()=>{currentAnalyticsTab=x.dataset.tab;document.querySelectorAll('#analyticsTabs .nav-link').forEach(y=>y.classList.toggle('active',y===x));if(currentAnalyticsTab==='ai')loadAIUsage(0);else renderAnalytics()});document.querySelectorAll('.analytics-filter').forEach(x=>x.onchange=loadAnalytics);document.querySelectorAll('.btn-period').forEach(x=>x.onclick=()=>{document.querySelectorAll('.btn-period').forEach(y=>y.classList.remove('active'));x.classList.add('active');periodDays=x.dataset.days==='custom'?'custom':Number(x.dataset.days);document.querySelectorAll('.custom-date').forEach(y=>y.classList.toggle('d-none',periodDays!=='custom'));if(periodDays!=='custom')loadAnalytics()});$('dateFrom').onchange=loadAnalytics;$('dateTo').onchange=loadAnalytics;function resetAnalyticsFilters(){document.querySelectorAll('.analytics-filter').forEach(x=>x.value='');aiCompanyFilter='';aiOperationFilter='';periodDays=0;document.querySelectorAll('.btn-period').forEach(x=>x.classList.toggle('active',x.dataset.days==='0'));document.querySelectorAll('.custom-date').forEach(x=>x.classList.add('d-none'));loadAnalytics()}

async function loadSettings(){try{const [x,a]=await Promise.all([api('/api/system-settings'),api('/api/ai/status')]);$('systemSettings').textContent=JSON.stringify({режим:x.admin_auth_enabled?'Защита входа включена':'Защита входа выключена',максимум_проверок:x.source_max_scan,поиск_по_сетке:x.yandex_grid?'Да':'Нет',поиск_по_фразам:x.search_provider_configured?'Подключён':'Не подключён',google_таблица:x.google_service_account_configured?'Подключена':'Не подключена'},null,2);$('aiStatus').textContent=a.status;$('aiStatus').classList.toggle('off',!a.configured);$('aiEnrichmentEnabled').checked=a.enrichment_enabled;$('aiPersonalizationEnabled').checked=a.personalization_enabled;$('aiDailyLimit').value=a.daily_request_limit;$('aiTechnical').textContent=`Модель: ${a.model}\nАдрес API: ${a.base_url}\nРежим рассуждений: отключён` }catch(e){$('systemSettings').textContent=e.message}}
async function saveAISettings(button){busy(button,true,'Сохраняем…');try{await api('/api/ai/settings',{method:'PATCH',body:JSON.stringify({enrichment_enabled:$('aiEnrichmentEnabled').checked,personalization_enabled:$('aiPersonalizationEnabled').checked,daily_request_limit:Number($('aiDailyLimit').value)})});notify('Настройки ИИ сохранены.');loadSettings()}catch(e){notify(e.message,true)}finally{busy(button,false)}}
async function testAI(button){busy(button,true,'Проверяем…');try{await api('/api/ai/test',{method:'POST'});notify('ИИ подключён.')}catch(e){notify(e.message,true)}finally{busy(button,false)}}
function confirmAction(title,text,buttonLabel,action){$('confirmTitle').textContent=title;$('confirmText').textContent=text;$('confirmButton').textContent=buttonLabel;$('confirmButton').onclick=async()=>{try{await action();modals.confirm.hide()}catch(e){notify(e.message,true)}};modals.confirm.show()}
function markDirty(form){dirtyForm=form;form.querySelector('.unsaved-note')?.classList.remove('d-none')}function clearDirty(){dirtyForm=null;document.querySelectorAll('.unsaved-note').forEach(x=>x.classList.add('d-none'))}document.querySelectorAll('.tracked-form').forEach(form=>form.addEventListener('input',()=>markDirty(form)));window.addEventListener('beforeunload',e=>{if(dirtyForm){e.preventDefault();e.returnValue=''}});document.querySelectorAll('.tracked-form').forEach(form=>form.closest('.modal').addEventListener('hidden.bs.modal',clearDirty));function showGlobal(message){$('globalAlert').textContent=message;$('globalAlert').classList.remove('d-none')}

document.addEventListener('DOMContentLoaded',async()=>{buildMenus();modals.direction=new bootstrap.Modal($('directionModal'));modals.mailbox=new bootstrap.Modal($('mailboxModal'));modals.template=new bootstrap.Modal($('templateModal'));modals.send=new bootstrap.Modal($('sendModal'));modals.aiUsage=new bootstrap.Modal($('aiUsageModal'));modals.confirm=new bootstrap.Modal($('confirmModal'));try{await loadBase()}catch(e){showGlobal(e.message)}const params=new URLSearchParams(location.search);showSection(pages[location.hash.slice(1)]?location.hash.slice(1):'home',false);if(params.get('company')){await openCompany(params.get('company'));if(params.get('draft'))await openSheetDraft(params.get('draft'))}});
